<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>چاپ فیش <?=htmlspecialchars($invoice['invoice_no'])?></title><link rel="stylesheet" href="/assets/style.css"></head><body class="print-page"><div class="print-toolbar no-print"><div><strong>مرحله چاپ فیش</strong><small>چاپگر: <?=htmlspecialchars($printers[0]['name']??'تعریف نشده')?></small></div><form method="post"><input type="hidden" name="action" value="print_receipt"><label>چاپگر<select name="printer_id" class="field"><?php foreach($printers as $p): ?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?> — <?=htmlspecialchars($p['paper_width'])?></option><?php endforeach; ?></select></label><button type="button" class="btn btn-primary" onclick="window.print()">چاپ فیش</button></form><a class="btn" href="/?page=invoice&id=<?=$invoice['id']?>">ویرایش فاکتور</a><a class="btn" href="/">داشبورد</a></div><?php if(!empty($message)): ?><div class="alert success no-print"><?=htmlspecialchars($message)?></div><?php endif; ?>
<main class="receipt" style="--receipt-width:<?=htmlspecialchars($settings['paper_width']??'80mm')?>"><header><?php if(($settings['show_logo']??'1')==='1'): ?><div class="receipt-logo">🍽</div><?php endif; ?><h1>رستوران</h1><?php if(($settings['show_address']??'1')==='1'): ?><small>آدرس رستوران</small><?php endif; ?><?php if(($settings['show_phone']??'1')==='1'): ?><small>تلفن رستوران</small><?php endif; ?></header><hr><?php if(($settings['show_invoice_no']??'1')==='1'): ?><div class="receipt-line"><span>فاکتور</span><b><?=htmlspecialchars($invoice['invoice_no'])?></b></div><?php endif; ?><?php if(($settings['show_date']??'1')==='1'): ?><div class="receipt-line"><span>تاریخ</span><span><?=htmlspecialchars($invoice['created_at'])?></span></div><?php endif; ?><?php if(($settings['show_customer']??'1')==='1'): ?><div class="receipt-line"><span>مشتری</span><span><?=htmlspecialchars($invoice['customer_name'])?></span></div><?php endif; ?><hr><?php foreach($items as $it): ?><div class="receipt-item"><div><b><?=htmlspecialchars($it['name'])?></b><small><?=number_format($it['unit_price'])?> × <?=htmlspecialchars($it['quantity'])?></small></div><strong><?=number_format($it['line_total'])?></strong></div><?php endforeach; ?><hr><div class="receipt-total"><span>مبلغ نهایی</span><strong><?=number_format($invoice['total_amount'])?> ریال</strong></div><?php if(($settings['show_payment']??'1')==='1'): ?><div class="receipt-line"><span>پرداخت</span><span><?=htmlspecialchars($invoice['payment_method']??'—')?></span></div><?php endif; ?><?php if(($settings['show_footer']??'1')==='1'): ?><footer><?=nl2br(htmlspecialchars($settings['footer_text']??''))?></footer><?php endif; ?></main><script>document.querySelector('.print-page')?.classList.add('ready');</script></body></html>